// Publishes, promotes, and revokes package versions in a file-backed local
// npm registry. The directory layout mirrors the npm registry API:
//   GET /<name>          -> registry/<name>/index.json   (packument)
//   GET /<name>/<file>   -> registry/<name>/<file>       (tarballs)
//   GET /channels/<c>.json                -> promotion record per channel
// Deterministic: packuments carry no timestamps and tarball URLs use the
// fixed serving origin, so identical inputs yield identical registry files.
const fs = require("fs");
const path = require("path");
const os = require("os");
const crypto = require("crypto");

const ORIGIN = "http://127.0.0.1:4873";
const REG = process.env.REGISTRY_DIR || "registry";
const pkg = require("./package.json");
const lock = require("./package-lock.json");

const sha1 = (f) => crypto.createHash("sha1").update(fs.readFileSync(f)).digest("hex");
const sri512 = (f) => "sha512-" + crypto.createHash("sha512").update(fs.readFileSync(f)).digest("base64");

function readPackument(name) {
  const file = path.join(REG, name, "index.json");
  if (!fs.existsSync(file)) return { _id: name, name, "dist-tags": {}, versions: {} };
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

function writePackument(name, doc) {
  fs.mkdirSync(path.join(REG, name), { recursive: true });
  fs.writeFileSync(path.join(REG, name, "index.json"), JSON.stringify(doc, null, 2) + "\n");
}

function tarballName(name, version) {
  return `${name}-${version}.tgz`;
}

function versionEntry(name, version, meta, tarballPath) {
  const entry = {
    _id: `${name}@${version}`,
    name,
    version,
    description: meta.description,
    main: meta.main,
    types: meta.types,
    license: meta.license,
    dist: {
      shasum: sha1(tarballPath),
      integrity: sri512(tarballPath),
      tarball: `${ORIGIN}/${name}/${tarballName(name, version)}`,
    },
  };
  // npm resolves dependency edges from packument metadata, not the tarball,
  // so dependency ranges must be propagated here or installs skip them.
  if (meta.dependencies) entry.dependencies = meta.dependencies;
  return entry;
}

// Extract a cached tarball by its SRI integrity (cacache content is
// content-addressed) and verify the bytes before publishing the mirror.
function cachedTarball(name, integrity) {
  const [, alg, b64] = integrity.match(/^(sha\d+)-(.+)$/);
  const hex = Buffer.from(b64, "base64").toString("hex");
  const cache = process.env.npm_config_cache || path.join(os.homedir(), ".npm", "_cacache");
  const src = path.join(cache, "content-v2", alg, hex.slice(0, 2), hex.slice(2, 4), hex.slice(4));
  const buf = fs.readFileSync(src);
  if ("sha512-" + crypto.createHash("sha512").update(buf).digest("base64") !== integrity) {
    throw new Error(`cache integrity mismatch for ${name}`);
  }
  return buf;
}

function publish() {
  const tgz = `${pkg.name}-${pkg.version}.tgz`;
  if (!fs.existsSync(tgz)) throw new Error(`${tgz} missing — run ./release.sh first`);
  const { name, version } = pkg;
  fs.mkdirSync(path.join(REG, name), { recursive: true });
  fs.copyFileSync(tgz, path.join(REG, name, tarballName(name, version)));
  const doc = readPackument(name);
  doc.versions[version] = versionEntry(name, version, pkg, path.join(REG, name, tarballName(name, version)));
  doc["dist-tags"].latest = version;
  writePackument(name, doc);

  // Mirror runtime dependencies from the local npm cache so installs from
  // this registry are fully self-contained.
  for (const [depPath, entry] of Object.entries(lock.packages)) {
    if (!depPath.startsWith("node_modules/")) continue;
    const depName = depPath.replace(/^node_modules\//, "");
    const depMeta = require(`./node_modules/${depName}/package.json`);
    const buf = cachedTarball(depName, entry.integrity);
    fs.mkdirSync(path.join(REG, depName), { recursive: true });
    fs.writeFileSync(path.join(REG, depName, tarballName(depName, entry.version)), buf);
    const depDoc = readPackument(depName);
    depDoc.versions[entry.version] = versionEntry(
      depName, entry.version, depMeta, path.join(REG, depName, tarballName(depName, entry.version))
    );
    depDoc["dist-tags"].latest = entry.version;
    writePackument(depName, depDoc);
  }
  console.log(`published ${name}@${version} to ${REG}/ (runtime deps mirrored from local cache)`);
}

function promote(channel, spec) {
  let name = pkg.name, version = pkg.version;
  if (spec) {
    const i = spec.lastIndexOf("@");
    name = spec.slice(0, i);
    version = spec.slice(i + 1);
  }
  const doc = readPackument(name);
  if (!doc.versions[version]) throw new Error(`${name}@${version} not published in ${REG}`);
  doc["dist-tags"][channel] = version;
  writePackument(name, doc);
  fs.mkdirSync(path.join(REG, "channels"), { recursive: true });
  const chanFile = path.join(REG, "channels", `${channel}.json`);
  const chan = fs.existsSync(chanFile) ? JSON.parse(fs.readFileSync(chanFile, "utf8")) : { channel, promoted: {} };
  chan.promoted[name] = version;
  fs.writeFileSync(chanFile, JSON.stringify(chan, null, 2) + "\n");
  console.log(`promoted ${name}@${version} to channel '${channel}'`);
}

function revoke(spec) {
  const i = spec.lastIndexOf("@");
  const name = spec.slice(0, i);
  const version = spec.slice(i + 1);
  const doc = readPackument(name);
  if (!doc.versions[version]) {
    console.log(`${name}@${version} is not present in ${REG} — nothing to revoke`);
    return;
  }
  delete doc.versions[version];
  for (const [tag, v] of Object.entries(doc["dist-tags"])) {
    if (v !== version) continue;
    const remaining = Object.keys(doc.versions).sort((a, b) => a.localeCompare(b, "en", { numeric: true }));
    if (remaining.length) doc["dist-tags"][tag] = remaining[remaining.length - 1];
    else delete doc["dist-tags"][tag];
  }
  writePackument(name, doc);
  const tgz = path.join(REG, name, tarballName(name, version));
  if (fs.existsSync(tgz)) fs.unlinkSync(tgz);
  if (fs.existsSync(path.join(REG, "channels"))) {
    for (const chanFile of fs.readdirSync(path.join(REG, "channels"))) {
      if (!chanFile.endsWith(".json") || chanFile === "revoked.json") continue;
      const chanPath = path.join(REG, "channels", chanFile);
      const chan = JSON.parse(fs.readFileSync(chanPath, "utf8"));
      if (chan.promoted[name] === version) {
        delete chan.promoted[name];
        fs.writeFileSync(chanPath, JSON.stringify(chan, null, 2) + "\n");
      }
    }
  }
  const revFile = path.join(REG, "channels", "revoked.json");
  const revoked = fs.existsSync(revFile) ? JSON.parse(fs.readFileSync(revFile, "utf8")) : {};
  revoked[`${name}@${version}`] = { removedFrom: REG, tarballDeleted: true };
  fs.writeFileSync(revFile, JSON.stringify(revoked, null, 2) + "\n");
  console.log(`revoked ${name}@${version} from ${REG} (tarball deleted, dist-tags and channels updated)`);
}

const [, , cmd, ...args] = process.argv;
if (cmd === "publish") publish();
else if (cmd === "promote") promote(args[0] || "release", args[1]);
else if (cmd === "revoke") revoke(args[0]);
else {
  console.error("usage: node registry-cli.js publish | promote <channel> [name@version] | revoke <name>@<version>");
  process.exit(1);
}
